import { Meta, StoryObj } from "@storybook/react";
import { expect, within } from "storybook/test";
import { BlockHeading, PageTitleProvider } from "./block-heading";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Modules/Block Heading",
  component: BlockHeading,
  parameters: {
    docs: {
      description: {
        component:
          "The title of a block on a content page. The page wraps its blocks in `PageTitleProvider` with the result " +
          "of `findPageTitle`, and each `BlockHeading` picks the tag that gives the page exactly one h1. When the " +
          "tag changes, the heading keeps the look of `tag`, so nothing moves on the page.",
      },
    },
  },
  argTypes: {
    className: { table: { disable: true } },
  },
  args: {
    blockId: "show",
    tag: "h2",
    children: "SLASH",
  },
} satisfies Meta<typeof BlockHeading>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantPageTitle: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Page title from findPageTitle" variantType="other">
      <Variant label="no PageTitleProvider: h2 as it is">
        <BlockHeading {...args} />
      </Variant>
      <Variant label="page title in this block: h2 becomes h1">
        <PageTitleProvider value={{ kind: "block", blockId: "show" }}>
          <BlockHeading {...args} />
        </PageTitleProvider>
      </Variant>
      <Variant label="page title in another block: h1 becomes h2">
        <PageTitleProvider value={{ kind: "block", blockId: "ride" }}>
          <BlockHeading {...args} tag="h1" />
        </PageTitleProvider>
      </Variant>
      <Variant label="no PageTitleProvider: h1 as it is">
        <BlockHeading {...args} tag="h1" />
      </Variant>
    </ShowcaseLayout>
  ),
};

export const TestTagFromPageTitle: Story = {
  render: (args) => (
    <>
      <PageTitleProvider value={{ kind: "block", blockId: "show" }}>
        <BlockHeading {...args} />
      </PageTitleProvider>
      <PageTitleProvider value={{ kind: "hidden" }}>
        <BlockHeading {...args} blockId="ride" tag="h1">
          Kvasten
        </BlockHeading>
      </PageTitleProvider>
    </>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole("heading", { level: 1, name: "SLASH" })).toHaveClass("h2");
    await expect(canvas.getByRole("heading", { level: 2, name: "Kvasten" })).toHaveClass("h1");
  },
};
