import { createContext, PropsWithChildren, useContext } from "react";
import { exhaustiveCheck } from "@/core/helpers/object-helper";
import type { PageTitle } from "@/core/helpers/page-title";
import { multipleClassNames } from "@/core/helpers/string-helper";
import styles from "./block-heading.module.less";

const PageTitleContext = createContext<PageTitle | null>(null);

/** Gives every BlockHeading inside it the page title from findPageTitle */
export const PageTitleProvider = PageTitleContext.Provider;

type HeadingTag = "h1" | "h2";

const keepMargins: Record<HeadingTag, string> = { h1: styles.keepH1Margins, h2: styles.keepH2Margins };

const demote = (tag: HeadingTag): HeadingTag => (tag === "h1" ? "h2" : tag);

const headingTag = (pageTitle: PageTitle | null, blockId: string | null | undefined, tag: HeadingTag): HeadingTag => {
  if (!pageTitle) return tag;
  switch (pageTitle.kind) {
    case "block":
      return pageTitle.blockId === blockId ? "h1" : demote(tag);
    case "own":
    case "hidden":
      return demote(tag);
    default:
      return exhaustiveCheck(pageTitle);
  }
};

const headingClassName = (className: string | undefined, tag: HeadingTag, renderedTag: HeadingTag) => {
  if (renderedTag === tag) return className;
  const keepLook = /\bh[1-6]\b/.test(className ?? "") ? undefined : tag;
  return multipleClassNames(className, keepLook, keepMargins[tag]);
};

export type BlockHeadingProps = PropsWithChildren<{
  /** Id of the block the heading belongs to. The heading is the h1 when the page title is in this block. */
  blockId?: string | null;
  /** The tag the heading has on its own. An h1 becomes an h2 when the page title is somewhere else. */
  tag: HeadingTag;
  className?: string;
}>;

/**
 * The title of a block, with the tag that gives the page exactly one h1. Without a PageTitleProvider it renders `tag`
 * as it is. When the tag changes, the heading keeps the look of `tag`: its class, unless `className` already has an
 * h1–h6 class, and its default margins.
 */
export const BlockHeading = ({ blockId, tag, className, children }: BlockHeadingProps) => {
  const Tag = headingTag(useContext(PageTitleContext), blockId, tag);
  return <Tag className={headingClassName(className, tag, Tag) || undefined}>{children}</Tag>;
};
